import React, { cloneElement, Ref, useState } from 'react';
import { ChipContainer } from './Chip.styles';
import { ChipRootProps } from './Chip.types';
import ChipContext from './ChipContext';
import { ChipDeleteIcon } from './components/ChipDeleteIcon/ChipDeleteIcon';

export const Chip = React.forwardRef(
  (
    { children, onClick, disabled = false, selected = false, ...restProps }: ChipRootProps,
    forwardedRef: Ref<HTMLDivElement>
  ): JSX.Element => {
    const [removable, setRemovable] = useState<boolean>(false);
    const contextValue = React.useMemo(() => ({ disabled }), [disabled]);

    const chipChildren = React.Children.map(
      children as React.ReactElement[],
      (child: React.ReactElement, index: number) => {
        if (child.type === ChipDeleteIcon && !removable) setRemovable(true);
        return cloneElement(child, {
          index,
          ...child.props,
        });
      }
    );

    const onKeyDown = (e: React.KeyboardEvent<HTMLElement>): void => {
      if ((e.key === 'Enter' || e.key === ' ') && !disabled) onClick?.();
    };

    return (
      <ChipContainer
        {...restProps}
        ref={forwardedRef}
        data-testid="chip-container"
        role="button"
        tabIndex={0}
        clickable={!!onClick}
        onClick={() => (!disabled ? onClick?.() : null)}
        onKeyDown={onKeyDown}
        removable={removable}
        selected={selected}
        disabled={disabled}
        aria-disabled={disabled || !onClick}
      >
        <ChipContext.Provider value={contextValue}>{chipChildren}</ChipContext.Provider>
      </ChipContainer>
    );
  }
);
